// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 t1, uint256 t2) public {
        t1 = bound(t1, 1, type(uint128).max);
        t2 = bound(t2, 1, t1); // second attempt not strictly later than first
        vm.deal(address(this), 20 ether);
        vm.warp(t1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        vm.warp(t2);
        // second call attempt (reverts in P since t2 <= t1, succeeds in M)
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        ok2; // return value irrelevant; only state rule is asserted
        // GENERAL RULE: pastBlockTime still equals the timestamp of the last
        // successful call (t1), regardless of the later attempt's outcome.
        assertTrue(c.pastBlockTime() == t1);
    }
}
